  const f = await bot.openFurnace(fBl);
  const raw = bot.inventory.items().find(i => i.name === 'raw_iron');
  const coal = bot.inventory.items().find(i => i.name === 'coal');
  await f.putInput(raw.type, null, toSmelt);
